import numpy as np

def perimeter_l1(r):
    # |x| + |y| <= r
    # Number of cells: (r+1)^2 + r^2
    # Perimeter is 4 * (r+1) ? Let's check
    # For r=1: (0,0), (1,0), (-1,0), (0,1), (0,-1)
    # Perimeter: 8 edges
    # For r=2: (0,0), (1,0), (-1,0), (0,1), (0,-1), (2,0), (-2,0), (0,2), (0,-2), (1,1), (1,-1), (-1,1), (-1,-1)
    # Boundary cells are those with |x|+|y| = r? No.
    # Let's just count.
    cells = []
    for x in range(-r, r+1):
        for y in range(-r, r+1):
            if abs(x) + abs(y) <= r:
                cells.append((x, y))

    p = 0
    for x, y in cells:
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in cells:
                p += 1
    return p

def perimeter_linf(r):
    # max(|x|, |y|) <= r
    # For r=1: (-1, -1) to (1, 1). 3x3 square.
    # Side length 2. Perimeter 4*2 = 8.
    # For r=n: Side length 2n. Perimeter 8n.
    cells = []
    for x in range(-r, r+1):
        for y in range(-r, r+1):
            if max(abs(x), abs(y)) <= r:
                cells.append((x, y))

    p = 0
    for x, y in cells:
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in cells:
                p += 1
    return p

for r in range(1, 11):
