def get_perimeter(n):
    cells = set()
    for x in range(-n, n + 1):
        for y in range(-(n - abs(x)), (n - abs(x)) + 1):
            cells.add((x, y))

    perimeter = 0
    for (x, y) in cells:
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in cells:
                perimeter += 1
    return perimeter

